        self.values.append(float(close))

        if len(self.values) < 2:
            return

        change = self.values[-1] - self.values[-2]
        gain = max(change, 0.0)
        loss = max(-change, 0.0)

        if self.average_gain is None:
            if len(self.values) < self.period + 1:
                return

            gains = []
            losses = []
            for i in range(1, len(self.values)):
                delta = self.values[i] - self.values[i - 1]
                gains.append(max(delta, 0.0))
                losses.append(max(-delta, 0.0))

            self.average_gain = sum(gains) / self.period
            self.average_loss = sum(losses) / self.period
        else:
            self.average_gain = (
                (self.average_gain * (self.period - 1)) + gain
            ) / self.period
            self.average_loss = (
                (self.average_loss * (self.period - 1)) + loss
            ) / self.period

        if self.average_loss == 0:
            self.value = 100.0
        else:
            relative_strength = self.average_gain / self.average_loss
            self.value = 100.0 - (100.0 / (1.0 + relative_strength))


class TickerState:
    def __init__(self, period=100):
        self.closes = deque(maxlen=period)
        self.previous_close = None
        self.previous_sma = None
        self.red_streak = 0
        self.rsi = Rsi14(14)

    def update(self, close):
        close = float(close)

        if self.previous_close is not None:
            if close < self.previous_close:
                self.red_streak += 1
            elif close > self.previous_close:
                self.red_streak = 0
            else:
                self.red_streak = 0

        self.previous_close = close
        self.closes.append(close)
        self.rsi.update(close)

    @property
    def sma_ready(self):
        return len(self.closes) == self.closes.maxlen

    @property
    def sma(self):
        if not self.sma_ready:
            return None
        return sum(self.closes) / len(self.closes)


class CompleteStrategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]
        self.states = {symbol: TickerState(100) for symbol in self.symbols}

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def OnData(self, data):
        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            for symbol in self.symbols:
                if data.Bars.ContainsKey(symbol):
                    self.states[symbol].update(data.Bars[symbol].Close)
            return

        bars = {symbol: data.Bars[symbol] for symbol in self.symbols}

        for symbol in self.symbols:
            self.states[symbol].update(bars[symbol].Close)

        spy_state = self.states[self.spy]
        aapl_state = self.states[self.aapl]

        spy_sma = spy_state.sma
        spy_cross_up = False
        spy_cross_down = False

        if spy_sma is not None and spy_state.previous_sma is not None:
            previous_close = spy_state.closes[-2]
            current_close = spy_state.closes[-1]

            spy_cross_up = (
                previous_close <= spy_state.previous_sma
                and current_close > spy_sma
            )
            spy_cross_down = (
                previous_close >= spy_state.previous_sma
                and current_close < spy_sma
            )

        spy_state.previous_sma = spy_sma

        if self.strategy_a_shares > 0 and spy_cross_down:
            self.MarketOrder(self.spy, -self.strategy_a_shares)
            self.strategy_a_shares = 0
        elif self.strategy_a_shares == 0 and spy_cross_up:
            portfolio_value = self.Portfolio.TotalPortfolioValue
            quantity = floor((portfolio_value * 0.40) / bars[self.spy].Close)
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.strategy_a_shares = quantity

        if self.strategy_b_shares > 0 and aapl_state.rsi.is_ready and aapl_state.rsi.value > 60:
            self.MarketOrder(self.aapl, -self.strategy_b_shares)
            self.strategy_b_shares = 0
        elif self.strategy_b_shares == 0 and aapl_state.red_streak >= 3:
            if self.Portfolio.Cash >= 20000:
                quantity = floor(20000 / bars[self.aapl].Close)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.strategy_b_shares = quantity
